import { config } from "dotenv";
import { resolve } from "path";

config({ path: resolve(__dirname, ".env.test") });

import { existsSync } from "node:fs";
import { loadEnvFile } from "node:process";
import path from "node:path";

// Load credentials from .env.test if present (same convention as the
// vercel-sandbox package), for the [real] compat tests that run against a
// live sandbox when RUN_INTEGRATION_TESTS=1.
const envPath = path.resolve(import.meta.dirname, ".env.test");
if (existsSync(envPath)) loadEnvFile(envPath);

import { MockServer } from "./server/mock-server.js";
import type { CommandHandler } from "./handlers.js";

/**
 * The process-wide mock server backing the drop-in {@link Sandbox} and
 * {@link Snapshot} exports. Each Vitest test file runs in its own module
 * instance, so this is already isolated per file; use {@link setupSandbox}'s
 * `resetHandlers` for isolation between tests in the same file.
 */
export const defaultServer = new MockServer();

interface MockDefaults {
  token: string;
  teamId: string;
  projectId: string;
  fetch: typeof globalThis.fetch;
}

/**
 * Inject the mock credentials and mocked `fetch` into a set of SDK params.
 * User-supplied fields win, but `fetch` is always the mock server so requests
 * can never escape to the network.
 */
export function withMockDefaults<T>(params: T): T & MockDefaults {
  return {
    ...defaultServer.credentials,
    ...(params ?? {}),
    fetch: defaultServer.fetch,
  } as T & MockDefaults;
}

/**
 * Control which commands are stubbed on the mock server. Handlers registered
 * here override just-bash execution for matching commands — the escape hatch
 * for commands just-bash can't run (e.g. `npm install`).
 *
 * Handlers are bound when a sandbox starts, so register them before
 * `Sandbox.create()`; adding handlers afterwards has no effect on an
 * already-running sandbox.
 *
 * @param handlers - Baseline handlers applied to every sandbox created
 *   afterwards.
 * @returns Controls to add per-test handlers (`use`) and reset state
 *   (`resetHandlers`), mirroring an MSW-style server.
 */
export function setupSandbox(...handlers: CommandHandler[]): {
  use: (...handlers: CommandHandler[]) => void;
  resetHandlers: () => void;
} {
  defaultServer.setDefaultHandlers(handlers);
  return {
    use: (...handlers: CommandHandler[]) => defaultServer.use(handlers),
    resetHandlers: () => {
      // MSW semantics: drop per-test `use()` overrides and in-memory state,
      // but restore the baseline handlers passed to this `setupSandbox` call
      // rather than wiping them.
      defaultServer.setDefaultHandlers(handlers);
      defaultServer.reset();
    },
  };
}

import { afterEach, describe, expect, test } from "vitest";
import { Sandbox } from "./sandbox";
import { command, setupSandbox } from "./index";

describe("command stubbing", () => {
  // Baseline handlers registered once, MSW-style, so `resetHandlers` must
  // preserve them across tests.
  const server = setupSandbox(command("npm install", { stdout: "installed\n" }));
  afterEach(() => server.resetHandlers());

  test("a default handler overrides just-bash for a matching command", async () => {
    const sandbox = await Sandbox.create();
    const result = await sandbox.runCommand("npm", ["install"]);
    expect(await result.stdout()).toContain("installed");
    await sandbox.stop();
  });

  test("use() registers a per-test handler that takes priority", async () => {
    server.use(command("deploy", { stdout: "deployed\n" }));
    const sandbox = await Sandbox.create();
    expect(await (await sandbox.runCommand("deploy", [])).stdout()).toContain("deployed");
    await sandbox.stop();
  });

  test("a regex handler can compute a response from args", async () => {
    server.use(
      command(/^echo-json/, (args) => ({ stdout: JSON.stringify(args), exitCode: 0 })),
    );
    const sandbox = await Sandbox.create();
    const result = await sandbox.runCommand("echo-json", ["a", "b"]);
    expect(JSON.parse(await result.stdout())).toEqual(["a", "b"]);
    await sandbox.stop();
  });

  test("resetHandlers drops use() overrides but keeps the baseline defaults", async () => {
    server.use(command("npm install", { stdout: "overridden\n" }));
    server.resetHandlers();
    const sandbox = await Sandbox.create();
    // The per-test override is gone, but the module-scope default persists.
    expect(await (await sandbox.runCommand("npm", ["install"])).stdout()).toContain("installed");
    await sandbox.stop();
  });

  test("use() overrides fall away after reset, restoring real execution", async () => {
    server.use(command("echo", { stdout: "stubbed\n" }));
    server.resetHandlers();
    const sandbox = await Sandbox.create();
    // With the override cleared and no baseline stub for `echo`, real
    // just-bash `echo` runs again.
    expect(await (await sandbox.runCommand("echo", ["real"])).stdout()).toBe("real\n");
    await sandbox.stop();
  });
});

import { inferScope } from "./project.js";
import {
  beforeEach,
  describe,
  test,
  vi,
  Mock,
  expect,
  onTestFinished,
} from "vitest";
import { fetchApi } from "./api.js";
import { NotOk } from "./error.js";
import * as fs from "node:fs/promises";
import * as path from "node:path";
import * as os from "node:os";

const fetchApiMock = fetchApi as Mock<typeof fetchApi>;
vi.mock("./api");

beforeEach(() => {
  vi.clearAllMocks();
});

async function getTempDir(): Promise<string> {
  const dir = await fs.mkdtemp(path.join(os.tmpdir(), "infer-scope-test-"));
  onTestFinished(() => fs.rm(dir, { recursive: true }));
  return dir;
}

function mockUserAndTeams({
  defaultTeamId = null as string | null,
  username = "my-user",
  teams = [] as Array<{
    id: string;
    slug: string;
    updatedAt: number;
    membership: { role: string };
    billing: { plan: string };
  }>,
} = {}) {
  return (opts: { endpoint: string }) => {
    if (opts.endpoint === "/v2/user") {
      return Promise.resolve({ user: { defaultTeamId, username } });
    }
    if (opts.endpoint.startsWith("/v2/teams")) {
      return Promise.resolve({
        teams,
        pagination: { count: teams.length, next: null },
      });
    }
    return Promise.resolve({});
  };
}

describe("team selection from paginated results", () => {
  test("prefers personal team (matching username slug) over most recently updated", async () => {
    fetchApiMock.mockImplementation(
      mockUserAndTeams({
        defaultTeamId: null,
        username: "my-user",
        teams: [
          {
            id: "team_other",
            slug: "other-team",
            updatedAt: 300,
            membership: { role: "OWNER" },
            billing: { plan: "hobby" },
          },
          {
            id: "team_personal",
            slug: "my-user",
            updatedAt: 100,
            membership: { role: "OWNER" },
            billing: { plan: "hobby" },
          },
        ],
      }),
    );

    const scope = await inferScope({ token: "token" });
    expect(scope.teamId).toBe("team_personal");
  });

  test("picks most recently updated hobby owner team when no username match", async () => {
    fetchApiMock.mockImplementation(
      mockUserAndTeams({
        defaultTeamId: null,
        username: "my-user",
        teams: [
          {
            id: "team_old",
            slug: "old-team",
            updatedAt: 100,
            membership: { role: "OWNER" },
            billing: { plan: "hobby" },
          },
          {
            id: "team_recent",
            slug: "recent-team",
            updatedAt: 300,
            membership: { role: "OWNER" },
            billing: { plan: "hobby" },
          },
        ],
      }),
    );

    const scope = await inferScope({ token: "token" });
    expect(scope.teamId).toBe("team_recent");
  });

  test("filters out non-OWNER and non-hobby teams", async () => {
    fetchApiMock.mockImplementation(
      mockUserAndTeams({
        defaultTeamId: null,
        username: "my-user",
        teams: [
          {
            id: "team_member",
            slug: "member-team",
            updatedAt: 300,
            membership: { role: "MEMBER" },
            billing: { plan: "hobby" },
          },
          {
            id: "team_pro",
            slug: "pro-team",
            updatedAt: 200,
            membership: { role: "OWNER" },
            billing: { plan: "pro" },
          },
          {
            id: "team_good",
            slug: "good-team",
            updatedAt: 100,
            membership: { role: "OWNER" },
            billing: { plan: "hobby" },
          },
        ],
      }),
    );

    const scope = await inferScope({ token: "token" });
    expect(scope.teamId).toBe("team_good");
  });

  test("keeps a team that is missing updatedAt (limited-access DTO)", async () => {
    fetchApiMock.mockImplementation(
      mockUserAndTeams({
        defaultTeamId: null,
        username: "my-user",
        // The limited-access team DTO omits `updatedAt`. The team must still be
        // selectable rather than failing the whole page.
        teams: [
          {
            id: "team_personal",
            slug: "my-user",
            membership: { role: "OWNER" },
            billing: { plan: "hobby" },
          } as never,
        ],
      }),
    );

    const scope = await inferScope({ token: "token" });
    expect(scope.teamId).toBe("team_personal");
  });

  test("skips malformed team entries instead of throwing", async () => {
    fetchApiMock.mockImplementation(async ({ endpoint }) => {
      if (endpoint === "/v2/user") {
        return { user: { defaultTeamId: null, username: "my-user" } };
      }
      if (endpoint.startsWith("/v2/teams")) {
        return {
          teams: [
            // Fully malformed entry (missing membership/billing) — must be dropped.
            { id: "team_broken", slug: "broken" },
            {
              id: "team_good",
              slug: "good-team",
              updatedAt: 100,
              membership: { role: "OWNER" },
              billing: { plan: "hobby" },
            },
          ],
          pagination: { count: 2, next: null },
        };
      }
      return {};
    });

    const scope = await inferScope({ token: "token" });
    expect(scope.teamId).toBe("team_good");
  });

  test("falls back to username when no hobby owner teams found", async () => {
    fetchApiMock.mockImplementation(
      mockUserAndTeams({
        defaultTeamId: null,
        username: "my-user",
        teams: [],
      }),
    );

    const scope = await inferScope({ token: "token" });
    expect(scope.teamId).toBe("my-user");
  });

  test("skips hobby team that matches already-tried defaultTeamId", async () => {
    fetchApiMock.mockImplementation(async ({ endpoint }) => {
      if (endpoint === "/v2/user") {
        return {
          user: { defaultTeamId: "team_abc", username: "my-user" },
        };
      }
      if (endpoint.startsWith("/v2/teams")) {
        return {
          teams: [
            {
              id: "team_abc",
              slug: "abc-team",
              updatedAt: 100,
              membership: { role: "OWNER" },
              billing: { plan: "hobby" },
            },
          ],
          pagination: { count: 1, next: null },
        };
      }
      // All project checks fail with 403
      throw new NotOk({ statusCode: 403, responseText: "Forbidden" });
    });

    await expect(inferScope({ token: "token" })).rejects.toThrowError(
      /none of the available teams allow sandbox creation/,
    );
    // team_abc tried once (defaultTeamId), then skipped in pagination, then username fallback
    const projectCalls = fetchApiMock.mock.calls.filter(([{ endpoint }]) =>
      endpoint.includes("vercel-sandbox-default-project"),
    );
    expect(projectCalls).toHaveLength(2);
  });

  test("paginates through multiple pages to find a usable team", async () => {
    fetchApiMock.mockImplementation(async ({ endpoint }) => {
      if (endpoint === "/v2/user") {
        return { user: { defaultTeamId: null, username: "my-user" } };
      }
      if (endpoint === "/v2/teams?limit=20") {
        return {
          teams: [
            {
              id: "team_pro",
              slug: "pro-team",
              updatedAt: 300,
              membership: { role: "OWNER" },
              billing: { plan: "pro" },
            },
          ],
          pagination: { count: 1, next: 12345 },
        };
      }
      if (endpoint === "/v2/teams?limit=20&until=12345") {
        return {
          teams: [
            {
              id: "team_hobby",
              slug: "hobby-team",
              updatedAt: 100,
              membership: { role: "OWNER" },
              billing: { plan: "hobby" },
            },
          ],
          pagination: { count: 1, next: null },
        };
      }
      return {};
    });

    const scope = await inferScope({ token: "token" });
    expect(scope.teamId).toBe("team_hobby");
  });
});

describe("inferScope", () => {
  test("uses provided teamId", async () => {
    fetchApiMock.mockResolvedValue({});
    const scope = await inferScope({ teamId: "my-team", token: "token" });
    expect(scope).toEqual({
      created: false,
      projectId: "vercel-sandbox-default-project",
      teamId: "my-team",
    });
  });

  describe("project creation", () => {
    test("project 404 triggers project creation", async () => {
      fetchApiMock.mockImplementation(async ({ method }) => {
        if (!method || method === "GET") {
          throw new NotOk({ statusCode: 404, responseText: "Not Found" });
        }
        return {};
      });
      const scope = await inferScope({ teamId: "my-team", token: "token" });
      expect(scope).toEqual({
        created: true,
        projectId: "vercel-sandbox-default-project",
        teamId: "my-team",
      });
    });

    test("non-404 throws when teamId is explicit", async () => {
      fetchApiMock.mockImplementation(async ({ method }) => {
        if (!method || method === "GET") {
          throw new NotOk({ statusCode: 403, responseText: "Forbidden" });
        }
        return {};
      });
      await expect(
        inferScope({ teamId: "my-team", token: "token" }),
      ).rejects.toThrowError(
        new NotOk({ statusCode: 403, responseText: "Forbidden" }),
      );
    });

    test("non-status errors are thrown", async () => {
      fetchApiMock.mockImplementation(async ({ method }) => {
        if (!method || method === "GET") {
          throw new Error("Oops!");
        }
        return {};
      });
      await expect(inferScope({ token: "token" })).rejects.toThrowError(
        "Oops!",
      );
    });
  });

  describe("fallback team selection with 403 handling", () => {
    test("falls back to hobby owner team when defaultTeamId returns 403", async () => {
      fetchApiMock.mockImplementation(async ({ endpoint }) => {
        if (endpoint === "/v2/user") {
          return {
            user: { defaultTeamId: "team_readonly", username: "my-user" },
          };
        }
        if (endpoint.startsWith("/v2/teams")) {
          return {
            teams: [
              {
                id: "team_writable",
                slug: "my-user",
                updatedAt: 100,
                membership: { role: "OWNER" },
                billing: { plan: "hobby" },
              },
            ],
            pagination: { count: 1, next: null },
          };
        }
        // Project check: 403 for readonly default team, success for owner team
        if (endpoint.includes("teamId=team_readonly")) {
          throw new NotOk({ statusCode: 403, responseText: "Forbidden" });
        }
        return {};
      });

      const scope = await inferScope({ token: "token" });
      expect(scope).toEqual({
        created: false,
        projectId: "vercel-sandbox-default-project",
        teamId: "team_writable",
        teamSlug: "my-user",
      });
    });

    test("throws helpful error when all candidates return 403", async () => {
      fetchApiMock.mockImplementation(async ({ endpoint }) => {
        if (endpoint === "/v2/user") {
          return {
            user: { defaultTeamId: "team_readonly", username: "my-user" },
          };
        }
        if (endpoint.startsWith("/v2/teams")) {
          return {
            teams: [
              {
                id: "team_owner",
                slug: "my-user",
                updatedAt: 200,
                membership: { role: "OWNER" },
                billing: { plan: "hobby" },
              },
            ],
            pagination: { count: 1, next: null },
          };
        }
        throw new NotOk({ statusCode: 403, responseText: "Forbidden" });
      });

      await expect(inferScope({ token: "token" })).rejects.toThrowError(
        /Authenticated as "my-user" but none of the available teams allow sandbox creation\./,
      );
    });

    test("uses defaultTeamId when it succeeds", async () => {
      fetchApiMock.mockImplementation(async ({ endpoint }) => {
        if (endpoint === "/v2/user") {
          return {
            user: { defaultTeamId: "team_default", username: "my-user" },
          };
        }
        if (endpoint.startsWith("/v2/teams")) {
          return { teams: [], pagination: { count: 0, next: null } };
        }
        return {};
      });

      const scope = await inferScope({ token: "token" });
      expect(scope).toEqual({
        created: false,
        projectId: "vercel-sandbox-default-project",
        teamId: "team_default",
      });
    });

    test("creates project in fallback team when it returns 404", async () => {
      fetchApiMock.mockImplementation(async ({ endpoint, method }) => {
        if (endpoint === "/v2/user") {
          return {
            user: { defaultTeamId: "team_default", username: "my-user" },
          };
        }
        if (endpoint.startsWith("/v2/teams")) {
          return { teams: [], pagination: { count: 0, next: null } };
        }
        if (
          endpoint.includes("teamId=team_default") &&
          (!method || method === "GET")
        ) {
          throw new NotOk({ statusCode: 404, responseText: "Not Found" });
        }
        return {};
      });

      const scope = await inferScope({ token: "token" });
      expect(scope).toEqual({
        created: true,
        projectId: "vercel-sandbox-default-project",
        teamId: "team_default",
      });
    });

    test("falls back to hobby owner team when defaultTeamId returns 402 RESOURCE_CREATION_BLOCKED", async () => {
      fetchApiMock.mockImplementation(async ({ endpoint }) => {
        if (endpoint === "/v2/user") {
          return {
            user: { defaultTeamId: "team_blocked", username: "my-user" },
          };
        }
        if (endpoint.startsWith("/v2/teams")) {
          return {
            teams: [
              {
                id: "team_writable",
                slug: "my-user",
                updatedAt: 100,
                membership: { role: "OWNER" },
                billing: { plan: "hobby" },
              },
            ],
            pagination: { count: 1, next: null },
          };
        }
        // 402 for the blocked team (RESOURCE_CREATION_BLOCKED)
        if (endpoint.includes("teamId=team_blocked")) {
          throw new NotOk({
            statusCode: 402,
            responseText: "RESOURCE_CREATION_BLOCKED: Your Team encountered an unknown problem.",
          });
        }
        return {};
      });

      const scope = await inferScope({ token: "token" });
      expect(scope).toEqual({
        created: false,
        projectId: "vercel-sandbox-default-project",
        teamId: "team_writable",
        teamSlug: "my-user",
      });
    });

    test("tries next candidate when project creation returns 403", async () => {
      fetchApiMock.mockImplementation(async ({ endpoint, method }) => {
