import { describe, it, expect } from "vitest";
import { Readable } from "stream";
import { pipeline } from "stream/promises";
import zlib from "zlib";
import tar from "tar-stream";
import { FileWriter } from "./file-writer.js";

async function extractFiles(readable: Readable) {
  const extract = tar.extract();
  const files = new Map<string, Buffer>();

  extract.on("entry", (header, stream, next) => {
    const chunks: Buffer[] = [];
    stream.on("data", (chunk: Buffer) => chunks.push(chunk));
    stream.on("end", () => {
      files.set(header.name, Buffer.concat(chunks));
      next();
    });
  });

  await pipeline(readable, zlib.createGunzip(), extract);
  return files;
}

describe("FileWriter", () => {
  it("writes ASCII buffer content", async () => {
    const writer = new FileWriter();
    await writer.addFile({
      name: "hello.txt",
      content: Buffer.from("Hello world"),
    });
    const end = writer.end();

    const files = await extractFiles(writer.readable);
    await end;
    expect(files.get("hello.txt")?.toString()).toBe("Hello world");
  });

  it("writes multi-byte UTF-8 buffer content", async () => {
    const writer = new FileWriter();
    const content = "café ☕ — Grüße aus München 🌍 日本語テスト";
    await writer.addFile({
      name: "utf8.txt",
      content: Buffer.from(content),
    });
    const end = writer.end();

    const files = await extractFiles(writer.readable);
    await end;
    expect(files.get("utf8.txt")?.toString()).toBe(content);
  });

  it("writes multiple files", async () => {
    const writer = new FileWriter();
    await writer.addFile({
      name: "a.txt",
      content: Buffer.from("file a"),
    });
    await writer.addFile({
      name: "b.txt",
      content: Buffer.from("file b"),
    });
    const end = writer.end();

    const files = await extractFiles(writer.readable);
    await end;
    expect(files.size).toBe(2);
    expect(files.get("a.txt")?.toString()).toBe("file a");
    expect(files.get("b.txt")?.toString()).toBe("file b");
  });

  it("writes string content", async () => {
    const writer = new FileWriter();
    await writer.addFile({
      name: "hello.txt",
      content: "Hello world",
    });
    const end = writer.end();

    const files = await extractFiles(writer.readable);
    await end;
    expect(files.get("hello.txt")?.toString()).toBe("Hello world");
  });

  it("writes multi-byte UTF-8 string content", async () => {
    const writer = new FileWriter();
    const content = "café ☕ — Grüße aus München 🌍 日本語テスト";
    await writer.addFile({
      name: "utf8.txt",
      content,
    });
    const end = writer.end();

    const files = await extractFiles(writer.readable);
    await end;
    expect(files.get("utf8.txt")?.toString()).toBe(content);
  });

  it("writes Uint8Array content", async () => {
    const writer = new FileWriter();
    const content = new TextEncoder().encode("Hello world");
    await writer.addFile({
      name: "hello.txt",
      content,
    });
    const end = writer.end();

    const files = await extractFiles(writer.readable);
    await end;
    expect(files.get("hello.txt")?.toString()).toBe("Hello world");
  });

  it("writes multi-byte UTF-8 Uint8Array content", async () => {
    const writer = new FileWriter();
    const text = "café ☕ — Grüße aus München 🌍 日本語テスト";
    const content = new TextEncoder().encode(text);
    await writer.addFile({
      name: "utf8.txt",
      content,
    });
    const end = writer.end();

    const files = await extractFiles(writer.readable);
    await end;
    expect(files.get("utf8.txt")?.toString()).toBe(text);
  });

  it("writes stream content with explicit size", async () => {
    const content = Buffer.from("streamed content");
    const writer = new FileWriter();
    await writer.addFile({
      name: "stream.txt",
      content: Readable.from(content),
      size: content.length,
    });
    const end = writer.end();

    const files = await extractFiles(writer.readable);
    await end;
    expect(files.get("stream.txt")?.toString()).toBe("streamed content");
  });
});

import type { Options as RetryOptions } from "async-retry";
import { APIError } from "./api-error.js";
import retry from "async-retry";

export interface RequestOptions {
  onRetry?(error: any, options: RequestOptions): void;
  retry?: Partial<RetryOptions>;
}

/**
 * Wraps a fetch function with retry logic. The retry logic will retry
 * on network errors, 429 responses and 5xx responses. The retry logic
 * will not retry on 4xx responses.
 *
 * @param rawFetch The fetch function to wrap.
 * @returns The wrapped fetch function.
 */
export function withRetry<T extends RequestInit>(
  rawFetch: (url: URL | string, init?: T) => Promise<Response>,
) {
  return async (
    url: URL | string,
    opts: T & RequestOptions = <T & RequestOptions>{},
  ) => {
    /**
     * Timeouts by default will be [400, 800]
     * before randomization is added.
     */
    const retryOpts = Object.assign(
      {
        minTimeout: 400,
        retries: 2,
        factor: 2,
      },
      opts.retry,
    );

    if (opts.onRetry) {
      retryOpts.onRetry = (error, attempts) => {
        opts.onRetry!(error, opts);
        if (opts.retry && opts.retry.onRetry) {
          opts.retry.onRetry(error, attempts);
        }
      };
    }

    try {
      return (await retry(async (bail, attempt) => {
        try {
          if (opts.signal?.aborted) {
            return bail(opts.signal.reason || new Error("Request aborted"));
          }
          const response = await rawFetch(url, opts);

          if (response.status === 429) {
            const retryAfter = Number(response.headers.get("Retry-After"));

            // Bail if the retry-after is in more than 20 seconds, as we don't
            // want to wait for that long before returning to the client.
            if (retryAfter > 20) {
              return bail(new APIError(response));
            }

            const hasRetriesRemaining =
              retryOpts.forever || attempt <= retryOpts.retries;
            if (retryAfter > 0 && hasRetriesRemaining) {
              await waitForRetry(retryAfter * 1000, opts.signal);
            }

            throw new APIError(response);
          }

          /**
           * If the response is a a retryable error, we throw in
           * order to retry.
           */
          if (response.status >= 500 && response.status < 600) {
            throw new APIError(response);
          }

          return response;
        } catch (error) {
          /**
           * If the request was aborted using the AbortController
           * we bail from retrying throwing the original error.
           */
          if (isAbortError(error)) {
            return bail(error);
          }

          /**
           * If the signal was aborted meanwhile we were
           * waiting, we bail from retrying.
           */
          if (opts.signal?.aborted) {
            return bail(opts.signal.reason || new Error("Request aborted"));
          }

          throw error;
        }
      }, retryOpts)) as Response;
    } catch (error) {
      /**
       * The ResponseError is only intended for retries so in case we
       * ran out of attempts we will respond with the last response
       * we obtained.
       */
      if (error instanceof APIError) {
        return error.response;
      }

      throw error;
    }
  };
}

async function waitForRetry(delay: number, signal?: AbortSignal | null) {
  if (signal?.aborted) {
    throw signal.reason || new Error("Request aborted");
  }

  await new Promise((resolve, reject) => {
    const onAbort = () => {
      clearTimeout(timeout);
      reject(signal?.reason || new Error("Request aborted"));
    };

    const timeout = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve(null);
    }, delay);

    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

function isAbortError(error: unknown): error is Error {
  return (
    error !== undefined &&
    error !== null &&
    (error as Error).name === "AbortError"
  );
}

import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import { APIError } from "@vercel/sandbox";
import { NotOk } from "@vercel/sandbox/dist/auth/index.js";

const isTokenFreshMock = vi.fn<() => boolean>();

vi.mock("../args/auth", () => ({
  isTokenFresh: () => isTokenFreshMock(),
}));

const { withFreshAuthRetry } = await import("./fresh-auth-retry");

function makeApiError(status: number): APIError<unknown> {
  return new APIError(
    new Response("", { status, statusText: "Unauthorized" }),
  );
}

function makeNotOk(statusCode: number): NotOk {
  return new NotOk({ statusCode, responseText: "no" });
}

/**
 * Await the result of a withFreshAuthRetry call that performs backoff via
 * async-retry's setTimeout. With vi.useFakeTimers active those timers don't
 * fire on their own; runAllTimersAsync drains them in parallel with the
 * awaiting test.
 */
async function awaitWithTimers<T>(promise: Promise<T>): Promise<T> {
  const settled = promise.then(
    (value) => ({ ok: true as const, value }),
    (error) => ({ ok: false as const, error }),
  );
  await vi.runAllTimersAsync();
  const result = await settled;
  if (result.ok) return result.value;
  throw result.error;
}

describe("withFreshAuthRetry", () => {
  beforeEach(() => {
    isTokenFreshMock.mockReset();
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it("returns the value on first success without retrying", async () => {
    isTokenFreshMock.mockReturnValue(true);
    const factory = vi.fn().mockResolvedValue("ok");
    await expect(awaitWithTimers(withFreshAuthRetry(factory))).resolves.toBe(
      "ok",
    );
    expect(factory).toHaveBeenCalledTimes(1);
  });

  it("retries on 401 when token is fresh and eventually succeeds", async () => {
    isTokenFreshMock.mockReturnValue(true);
    const factory = vi
      .fn()
      .mockRejectedValueOnce(makeApiError(401))
      .mockRejectedValueOnce(makeApiError(401))
      .mockResolvedValue("ok");
    await expect(awaitWithTimers(withFreshAuthRetry(factory))).resolves.toBe(
      "ok",
    );
    expect(factory).toHaveBeenCalledTimes(3);
  });

  it("retries on NotOk 403 from the vercel-sandbox auth layer", async () => {
    isTokenFreshMock.mockReturnValue(true);
    const factory = vi
      .fn()
      .mockRejectedValueOnce(makeNotOk(403))
      .mockResolvedValue("scope");
    await expect(awaitWithTimers(withFreshAuthRetry(factory))).resolves.toBe(
      "scope",
    );
    expect(factory).toHaveBeenCalledTimes(2);
  });

  it("throws the last 401 once retries are exhausted", async () => {
    isTokenFreshMock.mockReturnValue(true);
    const final = makeApiError(401);
    const factory = vi
      .fn()
      .mockRejectedValueOnce(makeApiError(401))
      .mockRejectedValueOnce(makeApiError(401))
      .mockRejectedValueOnce(makeApiError(401))
      .mockRejectedValue(final);
    await expect(awaitWithTimers(withFreshAuthRetry(factory))).rejects.toBe(
      final,
    );
    expect(factory).toHaveBeenCalledTimes(4);
  });

  it("does not retry auth errors when the token is not fresh", async () => {
    isTokenFreshMock.mockReturnValue(false);
    const err = makeApiError(401);
    const factory = vi.fn().mockRejectedValue(err);
    await expect(awaitWithTimers(withFreshAuthRetry(factory))).rejects.toBe(
      err,
    );
    expect(factory).toHaveBeenCalledTimes(1);
  });

  it("does not retry non-auth APIError statuses even when token is fresh", async () => {
    isTokenFreshMock.mockReturnValue(true);
    const err = makeApiError(500);
    const factory = vi.fn().mockRejectedValue(err);
    await expect(awaitWithTimers(withFreshAuthRetry(factory))).rejects.toBe(
      err,
    );
    expect(factory).toHaveBeenCalledTimes(1);
  });

  it("does not retry generic errors even when token is fresh", async () => {
    isTokenFreshMock.mockReturnValue(true);
    const err = new Error("boom");
    const factory = vi.fn().mockRejectedValue(err);
    await expect(awaitWithTimers(withFreshAuthRetry(factory))).rejects.toBe(
      err,
    );
    expect(factory).toHaveBeenCalledTimes(1);
  });
});

