// This file can also be imported as `@vercel/sandbox/dist/auth`, which is completely fine.
// The only valid importer of this would be the CLI as we share the same codebase.

export * from "./file.js";
export type * from "./file.js";
export * from "./oauth.js";
export type * from "./oauth.js";
export { pollForToken } from "./poll-for-token.js";
export { inferScope } from "./project.js";
export { NotOk } from "./error.js";

import path from "node:path";
import fs from "node:fs";
import { homedir } from "node:os";
import XDGAppPaths from "xdg-app-paths";
import { z } from "zod";
import { json } from "./zod.js";

const ZodDate = z.number().transform((seconds) => new Date(seconds * 1000));

const AuthFile = z.object({
  token: [REDACTED],
  refreshToken: [REDACTED],
  expiresAt: ZodDate.optional(),
});

const StoredAuthFile = json.pipe(AuthFile);

type AuthFile = z.infer<typeof AuthFile>;

// Returns whether a directory exists
const isDirectory = (path: string): boolean => {
  try {
    return fs.lstatSync(path).isDirectory();
  } catch (_) {
    // We don't care which kind of error occured, it isn't a directory anyway.
    return false;
  }
};

/**
 * Returns in which directory the config should be present.
 *
 * @internal The `VERCEL_AUTH_CONFIG_DIR` env var is for testing purposes only
 * and is not part of the public API.
 */
const getGlobalPathConfig = (): string => {
  if (process.env.VERCEL_AUTH_CONFIG_DIR) {
    return process.env.VERCEL_AUTH_CONFIG_DIR;
  }

  const vercelDirectories = XDGAppPaths("com.vercel.cli").dataDirs();

  const possibleConfigPaths = [
    ...vercelDirectories, // latest vercel directory
    path.join(homedir(), ".now"), // legacy config in user's home directory
    ...XDGAppPaths("now").dataDirs(), // legacy XDG directory
  ];

  // The customPath flag is the preferred location,
  // followed by the vercel directory,
  // followed by the now directory.
  // If none of those exist, use the vercel directory.
  return (
    possibleConfigPaths.find((configPath) => isDirectory(configPath)) ||
    vercelDirectories[0]
  );
};

export const getAuth = () => {
  try {
    const pathname = path.join(getGlobalPathConfig(), "auth.json");
    return StoredAuthFile.parse(fs.readFileSync(pathname, "utf8"));
  } catch {
    return null;
  }
};

export function updateAuthConfig(config: AuthFile): void {
  const pathname = path.join(getGlobalPathConfig(), "auth.json");
  fs.mkdirSync(path.dirname(pathname), { recursive: true });
  const content = {
    token: [REDACTED],
    expiresAt:
      config.expiresAt && Math.round(config.expiresAt.getTime() / 1000),
    refreshToken: [REDACTED],
  } satisfies z.input<typeof AuthFile>;
  fs.writeFileSync(pathname, JSON.stringify(content) + "\n");
}

import { z } from "zod";
import * as fs from "node:fs/promises";
import * as path from "node:path";
import { json } from "./zod.js";

const LinkedProjectSchema = json.pipe(
  z.object({
    projectId: z.string(),
    orgId: z.string(),
  }),
);

/**
 * Reads the linked project configuration from `.vercel/project.json`.
 *
 * @param cwd - The directory to search for `.vercel/project.json`.
 * @returns The linked project's `projectId` and `teamId`, or `null` if not found.
 */
export async function readLinkedProject(
  cwd: string,
): Promise<{ projectId: string; teamId: string } | null> {
  const projectJsonPath = path.join(cwd, ".vercel", "project.json");

  let content: string;
  try {
    content = await fs.readFile(projectJsonPath, "utf-8");
  } catch {
    return null;
  }

  const parsed = LinkedProjectSchema.safeParse(content);
  if (!parsed.success) {
    return null;
  }

  return {
    projectId: parsed.data.projectId,
    teamId: parsed.data.orgId,
  };
}

import { setTimeout } from "node:timers/promises";
import { updateAuthConfig } from "./file.js";
import { DeviceAuthorizationRequest, isOAuthError, OAuth } from "./oauth.js";

export type PollTokenItem =
  | { _tag: "Timeout"; newInterval: number }
  | { _tag: "SlowDown"; newInterval: number }
  | { _tag: "Error"; error: Error }
  | {
      _tag: "Response";
      response: { text(): Promise<string> };
    };

export async function* pollForToken({
  request,
  oauth,
}: {
  request: DeviceAuthorizationRequest;
  oauth: OAuth;
}): AsyncGenerator<PollTokenItem, void, void> {
  const controller = new AbortController();
  try {
    let intervalMs = request.interval * 1000;
    while (Date.now() < request.expiresAt) {
      const [tokenResponseError, tokenResponse] =
        await oauth.deviceAccessTokenRequest(request.device_code);

      if (tokenResponseError) {
        // 2x backoff on connection timeouts per spec https://datatracker.ietf.org/doc/html/rfc8628#section-3.5
        if (tokenResponseError.message.includes("timeout")) {
          intervalMs *= 2;
          yield { _tag: "Timeout" as const, newInterval: intervalMs };
          await setTimeout(intervalMs, { signal: controller.signal });
          continue;
        }
        yield { _tag: "Error" as const, error: tokenResponseError };
        return;
      }

      yield {
        _tag: "Response" as const,
        response: tokenResponse.clone() as { text(): Promise<string> },
      };

      const [tokensError, tokens] =
        await oauth.processTokenResponse(tokenResponse);

      if (isOAuthError(tokensError)) {
        const { code } = tokensError;
        switch (code) {
          case "authorization_pending":
            await setTimeout(intervalMs, { signal: controller.signal });
            continue;
          case "slow_down":
            intervalMs += 5 * 1000;
            yield { _tag: "SlowDown" as const, newInterval: intervalMs };
            await setTimeout(intervalMs, { signal: controller.signal });
            continue;
          default:
            yield { _tag: "Error", error: tokensError.cause };
            return;
        }
      }

      if (tokensError) {
        yield { _tag: "Error", error: tokensError };
        return;
      }

      updateAuthConfig({
        token: [REDACTED],
        expiresAt: new Date(Date.now() + tokens.expires_in * 1000),
        refreshToken: [REDACTED],
      });

      return;
    }

    yield {
      _tag: "Error" as const,
      error: new Error(
        "Timed out waiting for authentication. Please try again.",
      ),
    };
    return;
  } finally {
    controller.abort();
  }
}

export class NotOk extends Error {
  name = "NotOk";
  response: { statusCode: number; responseText: string };
  constructor(response: { statusCode: number; responseText: string }) {
    super(`HTTP ${response.statusCode}: ${response.responseText}`);
    this.response = response;
  }
}

import { z } from "zod";

/**
 * A Zod codec that serializes and deserializes JSON strings.
 */
export const json = z.string().transform((jsonString: string, ctx): unknown => {
  try {
    return JSON.parse(jsonString);
  } catch (err: any) {
    ctx.addIssue({
      code: z.ZodIssueCode.custom,
      message: `Invalid JSON: ${err.message}`,
    });
    return z.NEVER;
  }
});

import { z } from "zod";
import { fetchApi } from "./api.js";
import { NotOk } from "./error.js";
import { readLinkedProject } from "./linked-project.js";

const UserSchema = z.object({
  user: z.object({
    defaultTeamId: z.string().nullable(),
    username: z.string(),
  }),
});

const TeamSchema = z.object({
  id: z.string(),
  slug: z.string(),
  updatedAt: z.number().optional(),
  membership: z.object({
    role: z.string(),
  }),
  billing: z.object({
    plan: z.string(),
  }),
});

const TeamsSchema = z.object({
  // Parse each team independently and drop any that don't validate, so a single
  // malformed/limited team entry can never break candidate selection for the
  // whole page.
  teams: z.array(z.unknown()).transform((entries) =>
    entries.flatMap((entry) => {
      const parsed = TeamSchema.safeParse(entry);
      return parsed.success ? [parsed.data] : [];
    }),
  ),
  pagination: z.object({
    count: z.number(),
    next: z.number().nullable(),
  }),
});

const DEFAULT_PROJECT_NAME = "vercel-sandbox-default-project";

/** Status codes that mean "this team can't be used, try the next one". */
function isSkippableTeamError(e: unknown): boolean {
  return e instanceof NotOk && (e.response.statusCode === 402 || e.response.statusCode === 403);
}

/**
 * Resolves the team and project scope for sandbox operations.
 *
 * First checks for a locally linked project in `.vercel/project.json`.
 * If found, uses the `projectId` and `orgId` from there.
 *
 * Otherwise, if `teamId` is not provided, builds an ordered list of candidate
 * teams to try: the user's `defaultTeamId` first (if set), then hobby-plan
 * teams where the user has an OWNER role (preferring the personal team matching
 * the username, then the most recently updated). Tries each candidate until one
 * succeeds.
 *
 * @param opts.token - Vercel API authentication token.
 * @param opts.teamId - Optional team slug. If omitted, candidate teams are resolved automatically.
 * @param opts.cwd - Optional directory to search for `.vercel/project.json`. Defaults to `process.cwd()`.
 * @returns The resolved scope with `projectId`, `teamId`, and whether the project was `created`.
 *
 * @throws {NotOk} If the API returns an error other than 404 when checking the project.
 *
 * @example
 * ```ts
 * const scope = await inferScope({ token: "vercel_..." });
 * // => { projectId: "vercel-sandbox-default-project", teamId: "my-team", created: false }
 * ```
 */
export async function inferScope(opts: {
  token: string;
  teamId?: string;
  cwd?: string;
}): Promise<{
  projectId: string;
  teamId: string;
  created: boolean;
  teamSlug?: string;
  projectSlug?: string;
}> {
  const linkedProject = await readLinkedProject(opts.cwd ?? process.cwd());
  if (linkedProject) {
    const slugs = await resolveLinkedProjectSlugs(
      opts.token,
      linkedProject.teamId,
      linkedProject.projectId,
    );
    return { ...linkedProject, created: false, ...slugs };
  }

  if (opts.teamId) {
    return tryTeam(opts.token, opts.teamId);
  }

  const userData = await fetchApi({
    token: opts.token,
    endpoint: "/v2/user",
  }).then(UserSchema.parse);
  const { defaultTeamId, username } = userData.user;

  // 1. Try defaultTeamId first
  if (defaultTeamId) {
    try {
      const result = await tryTeam(opts.token, defaultTeamId);
      // Resolve team slug (best-effort)
      try {
        const team = await fetchApi({
          token: opts.token,
          endpoint: `/v2/teams/${encodeURIComponent(defaultTeamId)}`,
        }).then(z.object({ slug: z.string() }).parse);
        return { ...result, teamSlug: team.slug };
      } catch {
        return result;
      }
    } catch (e) {
      if (!isSkippableTeamError(e)) throw e;
    }
  }

  // 2. Paginate teams in pages of 20, try best hobby team per page
  let next: number | null = null;
  do {
    const endpoint: string =
      next === null
        ? "/v2/teams?limit=20"
        : `/v2/teams?limit=20&until=${next}`;
    const page = await fetchApi({ token: opts.token, endpoint }).then(
      TeamsSchema.parse,
    );

    next = page.pagination.next;

    const hobbyOwnerTeams = page.teams.filter(
      (t) => t.membership.role === "OWNER" && t.billing.plan === "hobby",
    );
    if (hobbyOwnerTeams.length === 0) {
      continue;
    }

    const bestHobbyTeam =
      hobbyOwnerTeams.find((t) => t.slug === username) ??
      hobbyOwnerTeams.sort((a, b) => (b.updatedAt ?? 0) - (a.updatedAt ?? 0))[0];

    if (bestHobbyTeam && bestHobbyTeam.id !== defaultTeamId) {
      try {
        const result = await tryTeam(opts.token, bestHobbyTeam.id);
        return { ...result, teamSlug: bestHobbyTeam.slug };
      } catch (e) {
        if (!isSkippableTeamError(e)) throw e;
      }
    }
  } while (next !== null);

  // 3. Fall back to username as personal team
  try {
    const result = await tryTeam(opts.token, username);
    return { ...result, teamSlug: username };
  } catch (e) {
    if (!isSkippableTeamError(e)) throw e;
  }

  throw new NotOk({
    statusCode: 403,
    responseText: `Authenticated as "${username}" but none of the available teams allow sandbox creation.`,
  });
}

/**
 * Attempts to use a specific team for sandbox operations by checking for
 * (or creating) the default project within that team.
 *
 * @returns The resolved scope if the team is usable.
 * @throws {NotOk} On authorization or other API errors.
 */
async function tryTeam(
  token: string,
  teamId: string,
): Promise<{ projectId: string; teamId: string; created: boolean }> {
  const teamParam = teamId.startsWith("team_")
    ? `teamId=${encodeURIComponent(teamId)}`
    : `slug=${encodeURIComponent(teamId)}`;

  let created = false;
  try {
    await fetchApi({
      token,
      endpoint: `/v2/projects/${encodeURIComponent(DEFAULT_PROJECT_NAME)}?${teamParam}`,
    });
  } catch (e) {
    if (!(e instanceof NotOk) || e.response.statusCode !== 404) {
      throw e;
    }

    await fetchApi({
      token,
      endpoint: `/v11/projects?${teamParam}`,
      method: "POST",
      body: JSON.stringify({
        name: DEFAULT_PROJECT_NAME,
      }),
    });
    created = true;
  }

  return { projectId: DEFAULT_PROJECT_NAME, teamId, created };
}

/**
 * Best-effort resolution of team slug and project name for a linked project.
 * Both IDs may be opaque (e.g. `team_xxx`, `prj_xxx`), so we fetch the
 * human-readable names from the API in parallel.
 */
async function resolveLinkedProjectSlugs(
  token: string,
  teamId: string,
  projectId: string,
): Promise<{ teamSlug?: string; projectSlug?: string }> {
  try {
    const teamParam = teamId.startsWith("team_")
      ? `teamId=${encodeURIComponent(teamId)}`
      : `slug=${encodeURIComponent(teamId)}`;
    const [teamData, projectData] = await Promise.all([
      fetchApi({
        token,
        endpoint: `/v2/teams/${encodeURIComponent(teamId)}`,
      }).then(z.object({ slug: z.string() }).parse),
      fetchApi({
        token,
        endpoint: `/v2/projects/${encodeURIComponent(projectId)}?${teamParam}`,
      }).then(z.object({ name: z.string() }).parse),
    ]);
    return { teamSlug: teamData.slug, projectSlug: projectData.name };
  } catch {
    return {};
  }
}

import os from "os";
import { z } from "zod";
import { VERSION } from "../version.js";

const USER_AGENT = `${os.hostname()} @ vercel/sandbox/${VERSION} node-${
  process.version
} ${os.platform()} (${os.arch()})`;

const ISSUER = new URL("https://vercel.com");
const CLIENT_ID = "cl_HYyOPBNtFMfHhaUn9L4QPfTZz6TP47bp";

const AuthorizationServerMetadata = z.object({
  issuer: z.string().url(),
  device_authorization_endpoint: z.string().url(),
  token_endpoint: z.string().url(),
  revocation_endpoint: z.string().url(),
  jwks_uri: z.string().url(),
  introspection_endpoint: z.string().url(),
});
type AuthorizationServerMetadata = z.infer<typeof AuthorizationServerMetadata>;
let _as: AuthorizationServerMetadata;

const DeviceAuthorization = z.object({
  device_code: z.string(),
  user_code: z.string(),
  verification_uri: z.string().url(),
  verification_uri_complete: z.string().url(),
  expires_in: z.number(),
  interval: z.number(),
});

const IntrospectionResponse = z
  .object({
    active: z.literal(true),
    client_id: z.string(),
    session_id: z.string(),
  })
  .or(z.object({ active: z.literal(false) }));

/**
 * Returns the Authorization Server Metadata
 *
 * @see https://openid.net/specs/openid-connect-discovery-1_0.html#ProviderConfigurationRequest
 * @see https://openid.net/specs/openid-connect-discovery-1_0.html#ProviderConfigurationResponse
 */
async function authorizationServerMetadata(): Promise<AuthorizationServerMetadata> {
  if (_as) return _as;

  const response = await fetch(
    new URL(".well-known/openid-configuration", ISSUER),
    {
      headers: { "Content-Type": "application/json", "user-agent": USER_AGENT },
    },
  );

  _as = AuthorizationServerMetadata.parse(await response.json());
  return _as;
}

export async function OAuth() {
  const as = await authorizationServerMetadata();
  return {
    /**
     * Perform the Device Authorization Request
     *
     * @see https://datatracker.ietf.org/doc/html/rfc8628#section-3.1
     * @see https://datatracker.ietf.org/doc/html/rfc8628#section-3.2
     */
    async deviceAuthorizationRequest(): Promise<DeviceAuthorizationRequest> {
      const response = await fetch(as.device_authorization_endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          "user-agent": USER_AGENT,
        },
        body: new URLSearchParams({
          client_id: CLIENT_ID,
          scope: "openid offline_access",
        }),
      });

      const json = await response.json();
      const parsed = DeviceAuthorization.safeParse(json);

      if (!parsed.success) {
        throw new OAuthError(
          "Failed to parse device authorization response from the Vercel authorization server.",
          json,
        );
      }

      return {
        device_code: parsed.data.device_code,
        user_code: parsed.data.user_code,
        verification_uri: parsed.data.verification_uri,
        verification_uri_complete: parsed.data.verification_uri_complete,
        expiresAt: Date.now() + parsed.data.expires_in * 1000,
        interval: parsed.data.interval,
      };
    },
    /**
     * Perform the Device Access Token Request
     *
     * @see https://datatracker.ietf.org/doc/html/rfc8628#section-3.4
     */
    async deviceAccessTokenRequest(
      device_code: string,
    ): Promise<[Error] | [null, Response]> {
      try {
        return [
          null,
          await fetch(as.token_endpoint, {
            method: "POST",
            headers: {
              "Content-Type": "application/x-www-form-urlencoded",
              "user-agent": USER_AGENT,
            },
            body: new URLSearchParams({
              client_id: CLIENT_ID,
              grant_type: "urn:ietf:params:oauth:grant-type:device_code",
              device_code,
            }),
            signal: AbortSignal.timeout(10 * 1000),
          }),
        ];
      } catch (error) {
        if (error instanceof Error) return [error];
        return [
          new Error("An unknown error occurred. See the logs for details.", {
            cause: error,
          }),
        ];
      }
    },
    /**
     * Process the Token request Response
     *
     * @see https://datatracker.ietf.org/doc/html/rfc8628#section-3.5
     */
    async processTokenResponse(
      response: Response,
    ): Promise<[OAuthError] | [null, TokenSet]> {
      const json = await response.json();
      const processed = TokenSet.safeParse(json);

      if (!processed.success) {
        return [
          new OAuthError(
            "Failed to parse token response from the Vercel authorization server.",
            json,
          ),
        ];
      }

      return [null, processed.data];
    },
    /**
     * Perform a Token Revocation Request.
     *
     * @see https://datatracker.ietf.org/doc/html/rfc7009#section-2.1
     * @see https://datatracker.ietf.org/doc/html/rfc7009#section-2.2
     */
    async revokeToken(token: string): Promise<OAuthError | void> {
      const response = await fetch(as.revocation_endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          "user-agent": USER_AGENT,
        },
        body: new URLSearchParams({ token, client_id: CLIENT_ID }),
      });

      if (response.ok) return;
      const json = await response.json();

      return new OAuthError("Revocation request failed", json);
    },
    /**
     * Perform Refresh Token Request.
     *
     * @see https://datatracker.ietf.org/doc/html/rfc6749#section-6
     */
    async refreshToken(token: string): Promise<TokenSet> {
      const response = await fetch(as.token_endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          "user-agent": USER_AGENT,
        },
        body: new URLSearchParams({
          client_id: CLIENT_ID,
          grant_type: "refresh_token",
          refresh_token: token,
        }),
      });

      const [tokensError, tokenSet] = await this.processTokenResponse(response);
      if (tokensError) throw tokensError;
      return tokenSet;
    },
    /**
     * Perform Token Introspection Request.
     *
     * @see https://datatracker.ietf.org/doc/html/rfc7662#section-2.1
     */
    async introspectToken(
      token: string,
    ): Promise<z.infer<typeof IntrospectionResponse>> {
      const response = await fetch(as.introspection_endpoint, {
        method: "POST",
        headers: {
          "Content-Type": "application/x-www-form-urlencoded",
          "user-agent": USER_AGENT,
        },
        body: new URLSearchParams({ token }),
      });

      const json = await response.json();
      const processed = IntrospectionResponse.safeParse(json);
      if (!processed.success) {
        throw new OAuthError(
          "Failed to parse introspection response from the Vercel authorization server.",
          json,
        );
      }

      return processed.data;
    },
  };
}

export type OAuth = Awaited<ReturnType<typeof OAuth>>;

const TokenSet = z.object({
  /** The access token issued by the authorization server. */
  access_token: z.string(),
  /** The type of the token issued */
  token_type: z.literal("Bearer"),
  /** The lifetime in seconds of the access token. */
  expires_in: z.number(),
  /** The refresh token, which can be used to obtain new access tokens. */
  refresh_token: [REDACTED],
  /** The scope of the access token. */
  scope: z.string().optional(),
});

type TokenSet = z.infer<typeof TokenSet>;

const OAuthErrorResponse = z.object({
  error: z.enum([
    "invalid_request",
    "invalid_client",
    "invalid_grant",
    "unauthorized_client",
    "unsupported_grant_type",
    "invalid_scope",
    "server_error",
    // Device Authorization Response Errors
    "authorization_pending",
    "slow_down",
    "access_denied",
    "expired_token",
    // Revocation Response Errors
    "unsupported_token_type",
  ]),
  error_description: z.string().optional(),
  error_uri: z.string().optional(),
});

type OAuthErrorResponse = z.infer<typeof OAuthErrorResponse>;

function processOAuthErrorResponse(
  json: unknown,
): OAuthErrorResponse | TypeError {
  try {
    return OAuthErrorResponse.parse(json);
  } catch (error) {
    if (error instanceof z.ZodError) {
      return new TypeError(`Invalid OAuth error response: ${error.message}`);
    }
    return new TypeError("Failed to parse OAuth error response");
  }
}

class OAuthError extends Error {
  name = "OAuthError";
  code: OAuthErrorResponse["error"];
  cause: Error;
  constructor(message: string, response: unknown) {
    super(message);
    const error = processOAuthErrorResponse(response);
    if (error instanceof TypeError) {
      this.cause = new Error(
        "Unexpected response from the Vercel authorization server.",
      );
      this.code = "server_error";
      return;
    }
    let cause = error.error;
    if (error.error_description) cause += `: ${error.error_description}`;
    if (error.error_uri) cause += ` (${error.error_uri})`;

    this.cause = new Error(cause);
    this.code = error.error;
  }
}

export function isOAuthError(error: unknown): error is OAuthError {
  return error instanceof OAuthError;
}

export interface DeviceAuthorizationRequest {
  /** The device verification code. */
  device_code: string;
  /** The end-user verification code. */
  user_code: string;
  /**
   * The minimum amount of time in seconds that the client
   * SHOULD wait between polling requests to the token endpoint.
   */
  interval: number;
  /** The end-user verification URI on the authorization server. */
  verification_uri: string;
  /**
   * The end-user verification URI on the authorization server,
   * including the `user_code`, without redirection.
   */
  verification_uri_complete: string;
  /**
   * The absolute lifetime of the `device_code` and `user_code`.
   * Calculated from `expires_in`.
   */
  expiresAt: number;
}
